{
  "name": "jwpapi-plugins",
  "description": "Julian Wagner's Claude Code plugins",
  "owner": {
    "name": "Julian Wagner"
  },
  "plugins": [
    {
      "name": "biome-claude-code-plugin",
      "description": "Biome LSP integration — instant lint diagnostics, format-on-stop",
      "version": "1.2.0",
      "author": {
        "name": "Julian Wagner"
      },
      "source": "./biome-lsp",
      "category": "development",
      "strict": false,
      "lspServers": {
        "biome": {
          "command": "npx",
          "args": ["biome", "lsp-proxy"],
          "extensionToLanguage": {
            ".ts": "typescript",
            ".tsx": "typescriptreact",
            ".js": "javascript",
            ".jsx": "javascriptreact",
            ".mjs": "javascript",
            ".cjs": "javascript",
            ".mts": "typescript",
            ".cts": "typescript",
            ".json": "json",
            ".jsonc": "jsonc",
            ".css": "css",
            ".graphql": "graphql"
          }
        }
      }
    }
  ]
}
